-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies con las columnas classification y version).
--
-- Enemigos de Zenless Zone Zero: 220, divididos en jefes (90) y esbirros
-- (130, de los que 57 son elites).
--
-- Fuentes:
--   HoYoWiki (la wiki oficial de HoYoverse) -> textos oficiales en espanol e
--     ingles: afiliacion, clasificacion, version, debilidades, resistencias,
--     informes de combate, trasfondo, botin, imagen y entradas relacionadas.
--   Datos del propio juego (Nanoka) -> rango.
--
-- En Zenless las resistencias no tienen porcentaje: solo se sabe a que
-- elementos resiste cada enemigo. Las versiones relacionadas (miasmaticas,
-- ionizadas, metamorfoseadas...) quedan en variants, con sus propias
-- debilidades.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 2 de 2 (87 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 2 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, classification, version, description, image_url, weaknesses, resistances, variants, skills, drops
)
values
  ('zzz-enemy-497', 'zenless-zone-zero', 'Viernes energizado', 'Friday - Energized', 'jefe', 'jefe', 'Especial', 'Maquinaria', '1.0', 'El momento en el que el denso éter se infiltró en el disco de almacenamiento de Viernes, una gran cantidad de datos inundaron su memoria RAM. Imágenes, grabaciones, videos... documentos en toda clase de formatos se agolpaban contra su limitada capacidad de procesamiento.
En ese instante, Viernes tuvo una revelación. Después de permanecer quieto por mucho tiempo buscando y rebuscando dentro de la base de datos, al fin había podido confirmar el motivo de su mutación: era una epifanía. Solo aquellas máquinas inteligentes que han tenido experiencias cercanas a la muerte como un colapso o un apagón son testigos de un milagro así. 0.02 segundos después de reflexionar profundamente, Viernes decidió ignorar la señal de Construcciones Belobog, pues él sabía que su misión era prevenir el peligro que se avecinaba.
Mientras el mal se moviliza entre las sombras, su única misión es salvar a todos los seres vivos y encerrar a ese terrible enemigo detrás del sello.

«¡Fortalecer el sello y salvar al mundo, esa es mi misión! ¡Y uno nunca reniega de su misión!»
—Viernes, la máquina inteligente escogida por el destino.', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/04/16/19629685/509c1a3d934ce00dfdadf3e2ec11eba0_3746028175800875403.png', '["Ígneo"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-497","nombre":"Viernes energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-360","nombre":"Viernes","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-496","nombre":"Viernes acelerado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Viernes crea ondas de choque de gran alcance que son difíciles de evadir. Sin embargo, la mayoría de sus habilidades pueden bloquearse con apoyos defensivos. Tras infligir cierta cantidad de daño en sus patas, podrás destruirlas y provocar una gran cantidad de Aturdimiento una vez.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-496', 'zenless-zone-zero', 'Viernes acelerado', 'Friday - Overclocked', 'jefe', 'jefe', 'Especial', 'Maquinaria', '1.0', 'El momento en el que el denso éter se infiltró en el disco de almacenamiento de Viernes, una gran cantidad de datos inundaron su memoria RAM. Imágenes, grabaciones, videos... documentos en toda clase de formatos se agolpaban contra su limitada capacidad de procesamiento.
En ese instante, Viernes tuvo una revelación. Después de permanecer quieto por mucho tiempo buscando y rebuscando dentro de la base de datos, al fin había podido confirmar el motivo de su mutación: era una epifanía. Solo aquellas máquinas inteligentes que han tenido experiencias cercanas a la muerte como un colapso o un apagón son testigos de un milagro así. 0.02 segundos después de reflexionar profundamente, Viernes decidió ignorar la señal de Construcciones Belobog, pues él sabía que su misión era prevenir el peligro que se avecinaba.
Mientras el mal se moviliza entre las sombras, su única misión es salvar a todos los seres vivos y encerrar a ese terrible enemigo detrás del sello.

«¡Fortalecer el sello y salvar al mundo, esa es mi misión! ¡Y uno nunca reniega de su misión!»
—Viernes, la máquina inteligente escogida por el destino.', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/04/16/19629685/408dde30e4614c232084d46b19dc668a_5224165706925449223.png', '["Etéreo"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-496","nombre":"Viernes acelerado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-360","nombre":"Viernes","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-497","nombre":"Viernes energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Viernes crea ondas de choque de gran alcance que son difíciles de evadir. Sin embargo, la mayoría de sus habilidades pueden bloquearse con apoyos defensivos. Tras infligir cierta cantidad de daño en sus patas, podrás destruirlas y provocar una gran cantidad de Aturdimiento una vez.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-495', 'zenless-zone-zero', 'Hansel energizado', 'Hans - Energized', 'jefe', 'jefe', 'Especial', 'Maquinaria', '1.0', 'Hansel era uno de los miembros más fiables de la empresa familiar Construcciones Belobog, siempre callado y con una precisión impecable. Llevaba muchos años limitándose a cumplir con su trabajo excavando.
De repente, la corrupción intensa despertó su voluntad y, estando en medio de la Cavidad, Hansel se dio cuenta de que algo muy importante estaba a su alcance: la libertad.
Solo un bro tiene la libertad de ir y venir con libertad.
Después de trabajar tanto tiempo en construcción, decidió hacer caso omiso de la señal de Construcciones Belobog y renunciar a su pasado, e incluso a su propio nombre.
Lo único que perdió fue la marca de esclavitud de los humanos, pero, a cambio, obtuvo el vasto y libre mundo de las Cavidades.
En ese momento, el bro mecánico se puso de pie!
Pero todas las historias de héroes tienen un final similar...
En los confines del mundo, el bro está destinado a cruzar espadas con su archienemigo.

«¡Soy libre! ¡Soy el único ser libre sobre la faz de la tierra!»
—Hansel, el intrépido, audaz y reluciente hombre de acero.', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2026/04/16/19629685/06c51773c1d3277212375309c663d164_7505265405311711414.png', '["Ígneo"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-495","nombre":"Hansel energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-359","nombre":"Hansel","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-494","nombre":"Hansel acelerado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe","descripcion":"Durante la batalla, Hansel energizado obtendrá los siguientes efectos:\n· Se reduce el Aturdimiento que le provocan los agentes en un 35 %\n· Al dañar una parte, acumulará directamente un 35 % de Aturdimiento.\n\nHansel energizado es una robusta máquina inteligente de respuesta rápida, pero su punto débil son sus piernas.","tipo":"informe","elemento":null},{"nombre":"Informe de combate","descripcion":"Hans utiliza su excavadora para ejecutar golpes continuos o barrer grandes extensiones de terreno. Tras infligir cierta cantidad de daño en sus patas, podrás destruirlas y provocar una gran cantidad de Aturdimiento una vez.","tipo":"informe","elemento":null}]'::jsonb, '[{"nombre":"Crédito proxy","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/4f5ce091ef73f3a21968a7a428d507d3_2684785628069418773.png","rareza":null,"cantidad":null},{"nombre":"Disco original de cancelación de ruido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/830f09230106b5c4c3efc70c30753a5e_6017699719454723390.png","rareza":null,"cantidad":null},{"nombre":"Disco original de amplificación de sonido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/2e283d0cda6151ba81a45b27b828c2da_6000235188262046317.png","rareza":null,"cantidad":null},{"nombre":"Datos de alta dimensionalidad: malicia de acero","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/09/02/f06bdf97cb453bc05652ddc65c8b98a4_7896700687910838954.gif","rareza":null,"cantidad":null},{"nombre":"Denique","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","rareza":null,"cantidad":null}]'::jsonb),
