  ('zzz-enemy-426', 'zenless-zone-zero', 'Dullahan infame', 'Notorious - Dullahan', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'Un poderoso ser etéreo humanoide que se vio por primera vez en la Cavidad Lagunaria, cuyos apuntes se encuentran en los informes de la tercera expedición de la Asociación de Investigación de Cavidades. Hasta ahora, se desconoce si el origen de este organismo etéreo está relacionado con la caída de Bruz, la ciudad aledaña.
Debido a su gran fuerza y sus técnicas inteligentes de pelea, la Asociación de Investigación de Cavidades lo clasifica como un riesgo medio. Se recomienda a los Investigadores novatos mantener la distancia y evitar la confrontación directa con ellos.

«No dejes que ilumine su espada y si lo hace... ino dejes que te corte la cabeza!»— Segmento del programa de variedades de edición especial «¡Enséñame, líder!»', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/03/132470628/7cd5c5962395356bd88a64f58c142a7a_1186992101314150059.png', '["Glacial","Etéreo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-426","nombre":"Dullahan infame","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-429","nombre":"Dullahan","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-430","nombre":"Dullahan ionizado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]},{"id":"zzz-enemy-428","nombre":"Dullahan energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Eléctrico","valor":null}]},{"id":"zzz-enemy-425","nombre":"Cría de dullahan","debilidades":["Glacial","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe actual - Sala de desafío experto","descripcion":"El dullahan infame se unirá al campo de batalla tras 20 segundos y, tras aparecer, aplicará los siguientes efectos a todos los enemigos:\n\n· Cuando el enemigo no está afectado por Aturdimiento, el daño que le infligen los agentes se reduce en un 30 %.\n· El Aturdimiento que le provocan los agentes aumenta en un 35 %.\n· La velocidad de recuperación de Aturdimiento se reduce en un 30 %.\nSi los enemigos son derrotados antes de tiempo, el dullahan infame se unirá al campo de batalla instantáneamente con un 20 % de Aturdimiento acumulado.\n\nEl dullahan infame es un ser etéreo hábil en ataques cargados cuerpo a cuerpo y en técnicas de asalto, lo cual le proporciona un ritmo de combate propio.","tipo":"informe","elemento":null},{"nombre":"Informe de combate - Archivo de Faetón","descripcion":"El dullahan infame acumula fuerza para después arrojarse hacia delante con un poderoso espadazo. Mientras acumula fuerza, utiliza ataques de gran poder para interrumpirlo. Además, el dullahan infame usa hábilmente su escudo para bloquear ataques. Tras bloquearlos, enlaza rápidamente una habilidad.","tipo":"informe","elemento":null}]'::jsonb, '[{"nombre":"Crédito proxy","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/4f5ce091ef73f3a21968a7a428d507d3_2684785628069418773.png","rareza":null,"cantidad":400},{"nombre":"Disco original de cancelación de ruido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/830f09230106b5c4c3efc70c30753a5e_6017699719454723390.png","rareza":null,"cantidad":null},{"nombre":"Disco original de amplificación de sonido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/2e283d0cda6151ba81a45b27b828c2da_6000235188262046317.png","rareza":null,"cantidad":null},{"nombre":"Datos de alta dimensionalidad: obituario draconiano","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/09/03/114a81f3f7580b2abc211361b8688ef5_5892410292809904179.gif","rareza":null,"cantidad":null},{"nombre":"Denique","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","rareza":null,"cantidad":null}]'::jsonb),
  ('zzz-enemy-425', 'zenless-zone-zero', 'Cría de dullahan', 'Newborn Dullahan', 'esbirro', 'elite', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'Un poderoso ser etéreo humanoide que se vio por primera vez en la Cavidad Lagunaria, cuyos apuntes se encuentran en los informes de la tercera expedición de la Asociación de Investigación de Cavidades. Hasta ahora, se desconoce si el origen de este organismo etéreo está relacionado con la caída de Bruz, la ciudad aledaña.
Debido a su gran fuerza y sus técnicas inteligentes de pelea, la Asociación de Investigación de Cavidades lo clasifica como un riesgo medio. Se recomienda a los Investigadores novatos mantener la distancia y evitar la confrontación directa con ellos.

«No dejes que ilumine su espada y si lo hace... ino dejes que te corte la cabeza!»- Segmento del programa de variedades de edición especial «¡Enséñame, líder!»', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/03/132470628/f1019a185469454e80906deb75cdd3f4_3155186325109344856.png', '["Glacial","Etéreo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-425","nombre":"Cría de dullahan","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-429","nombre":"Dullahan","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-428","nombre":"Dullahan energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Eléctrico","valor":null}]},{"id":"zzz-enemy-430","nombre":"Dullahan ionizado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]},{"id":"zzz-enemy-426","nombre":"Dullahan infame","debilidades":["Glacial","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"El dullahan acumula fuerza para después arrojarse hacia delante con un poderoso espadazo. Mientras acumula fuerza, utiliza ataques de gran poder para interrumpirlo.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-424', 'zenless-zone-zero', 'Bandido de Cavidades - bárbaro desenfrenado', 'Hollow Thug - Rampant Brute', 'jefe', 'jefe', 'Bandidos', 'Orgánicos', '1.1', 'Los bandidos de las Cavidades son un grupo de lo más variopinto. El único motivo por el que se juntan es para robar recursos etéreos y lucrarse de ello.
Originalmente, esta banda desorganizada no tenía unas normas establecidas. Sin embargo, en el momento en que aparecieron los temibles e icónicos bárbaros desenfrenados, se establecieron unas reglas. Llevan un sistema de propulsión auxiliar para la construcción que les ayuda conseguir materiales de construcción que emplean como armas de usar y tirar. Al parecer, este equipo tan pesado y sus armas les bastan para destrozar a un hombre poderoso. Aunque, para ellos, es como al simplemente fuera ropa de entrenamiento de su talla.
Golpear, destrozar, aplastar... Hasta el más simple de los movimientos de lucha es suficiente para pulverizar a un enemigo en un duelo mortal. No dudan en exhibir su fuerza incomparable en cualquier momento y lugar.
Asimismo, las investigaciones del Ministerio de Seguridad Pública demuestran que, en muchas ocasiones, los bárbaros desenfrenados que lideran a los bandidos de Cavidades idolatran una particular cultura del ejercicio al aire libre. Tanto es así, que han dado vida a una extraña comunidad muy unida entre si.

«¿Cómo? ¿Dices que los entrenadores del gimnasio son más fuertes que el vinagre?»
«Ja, ja, ja, no tienes ni Ideal»
«Primero únete a nosotros y entrena con nuestro jefe durante tres semanas... ¡Te aseguro que tendrás los mejores bíceps del barrio!»
— En algún lugar de Nueva Eridu, unos bandidos de Cavidades intentando reclutar nuevos miembros', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/02/132470628/e68571c284b428625855ad14ffa87777_2192915920062388937.png', '["Físico","Ígneo"]'::jsonb, '[{"elemento":"Glacial","valor":null}]'::jsonb, '[{"id":"zzz-enemy-424","nombre":"Bandido de Cavidades - bárbaro desenfrenado","debilidades":["Físico","Ígneo"],"resistencias":[{"elemento":"Glacial","valor":null}]},{"id":"zzz-enemy-1017","nombre":"Bárbaro desenfrenado miasmático","debilidades":["Etéreo","Aéreo"],"resistencias":[{"elemento":"Eléctrico","valor":null}]}]'::jsonb, '[{"nombre":"Informe actual","descripcion":"Durante la batalla, el bandido de Cavidades: bárbaro desenfrenado obtendrá los siguientes efectos.\n· Durante su estado de carga, aumenta el daño que inflige en un 50 %, pero también aumenta la acumulación de Anomalia de Atributo que causan los agentes en un 30 %.\n· Cuando esté afectado por una Anomalía de Atributo, el bárbaro desenfrenado pierde inmediatamente un 5 % de PV.\n\nEl bandido de Cavidades: bárbaro desenfrenado supone una gran amenaza, por lo que es necesario prestar atención constantemente a su estado de carga. ¡lgnorar su estado puede resultar en un desastre colosal!","tipo":"informe","elemento":null},{"nombre":"Informe de combate","descripcion":"El bandido de Cavidades: bárbaro desenfrenado recarga sus brazos acorazados para liberar ataques más potentes. Sin embargo, mientras recarga, el bárbaro desenfrenado se encuentra en el estado de electrochoque. Si aplicas otro tipo de Anomalía de Atributo, provocarás el estado de disfunción e interrumpirás su recarga.","tipo":"informe","elemento":null}]'::jsonb, '[{"nombre":"Crédito proxy","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/4f5ce091ef73f3a21968a7a428d507d3_2684785628069418773.png","rareza":null,"cantidad":400},{"nombre":"Disco original de cancelación de ruido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/830f09230106b5c4c3efc70c30753a5e_6017699719454723390.png","rareza":null,"cantidad":null},{"nombre":"Disco original de amplificación de sonido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/2e283d0cda6151ba81a45b27b828c2da_6000235188262046317.png","rareza":null,"cantidad":null},{"nombre":"Datos de alta dimensionalidad: caída meteórica","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2024/08/26/403606926/a8f0be46677977b72c80b8a8368c0f0d_6203482409769363793.gif","rareza":null,"cantidad":null},{"nombre":"Denique","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","rareza":null,"cantidad":null}]'::jsonb),
  ('zzz-enemy-423', 'zenless-zone-zero', 'Tánatos energizado', 'Thanatos - Energized', 'esbirro', 'elite', 'Mutaciones etéreas', 'Ser etéreo', '1.0', null, 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/01/132470628/e87d420adcf592479a2cf6a30f91cb03_9137721133000300498.png', '["Ígneo"]'::jsonb, '[{"elemento":"Eléctrico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-423","nombre":"Tánatos energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Eléctrico","valor":null}]},{"id":"zzz-enemy-422","nombre":"Tánatos","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-421","nombre":"Tánatos ionizado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]},{"id":"zzz-enemy-420","nombre":"Tánatos infame","debilidades":["Glacial","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe","descripcion":"El tánatos se teletransporta para atacar desde un ángulo estratégico. Sin embargo, al ejecutar apoyos defensivos y ataques sucesivos, acumulará una gran cantidad de Aturdimiento.","tipo":"informe","elemento":null},{"nombre":"Informe actual","descripcion":"Explorar las Cavidades supone una carga mental considerable. Encima de ello, la capacidad de movimiento instantáneo y los ataques impredecibles del tánatos son el terror de un gran número de saqueadores de Cavidades.\nMuchos de ellos incluso han perdido el valor después de enfrentarse a un tánatos a solas y han decidido retirarse antes de tiempo. Incluso se ha vuelto un tema recurrente en las películas de terror.\n\n«Su esbelta figura desaparece en un abrir y cerrar de ojos, y antes de que te des cuenta está detrás de ti...»\n«¡Aaah! ¡Ahora no me atrevo a ir al baño a solas!»\n- Reseña en la página web «Ciruela de cobre» la noche del estreno de «Cuando el ser etéreo toca la puerta»","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-422', 'zenless-zone-zero', 'Tánatos', 'Thanatos', 'esbirro', 'elite', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'Explorar las Cavidades supone una carga mental considerable. Encima de ello, la capacidad de movimiento instantáneo y los ataques impredecibles del tánatos son el terror de un gran número de saqueadores de Cavidades.
Muchos de ellos incluso han perdido el valor después de enfrentarse a un tánatos a solas y han decidido retirarse antes de tiempo. Incluso se ha vuelto un tema recurrente en las películas de terror.

«Su esbelta figura desaparece en un abrir y cerrar de ojos, y antes de que te des cuenta está detrás de ti...»
«¡Aaah! ¡Ahora no me atrevo a ir al baño a solas!»
- Reseña en la página web «Ciruela de cobre» la noche del estreno de «Cuando el ser etéreo toca la puerta»', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/01/132470628/b2432fa01f3672f13376d996d2647973_535556312500989393.png', '["Glacial","Etéreo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-422","nombre":"Tánatos","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-423","nombre":"Tánatos energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Eléctrico","valor":null}]},{"id":"zzz-enemy-421","nombre":"Tánatos ionizado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]},{"id":"zzz-enemy-420","nombre":"Tánatos infame","debilidades":["Glacial","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"El tánatos se teletransporta para atacar desde un ángulo estratégico. Sin embargo, al ejecutar apoyos defensivos y ataques sucesivos, acumulará una gran cantidad de Aturdimiento.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-421', 'zenless-zone-zero', 'Tánatos ionizado', 'Ionized - Thanatos', 'esbirro', 'elite', 'Mutaciones etéreas', 'Ser etéreo', '1.0', null, 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/01/132470628/5eb4422f04c00c77cd8188a0cf983463_1474783312654891482.png', '["Etéreo"]'::jsonb, '[{"elemento":"Glacial","valor":null}]'::jsonb, '[{"id":"zzz-enemy-421","nombre":"Tánatos ionizado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]},{"id":"zzz-enemy-422","nombre":"Tánatos","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-423","nombre":"Tánatos energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Eléctrico","valor":null}]},{"id":"zzz-enemy-420","nombre":"Tánatos infame","debilidades":["Glacial","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"El tánatos ionizado se teletransporta para atacar desde un ángulo estratégico. Sin embargo, al ejecutar apoyos defensivos y ataques sucesivos, acumulará una gran cantidad de Aturdimiento.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-420', 'zenless-zone-zero', 'Tánatos infame', 'Notorious - Thanatos', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'El tánatos infame se teletransporta para atacar desde un ángulo estratégico. Sus ataques serán extremadamente poderosos. Sin embargo, al ejecutar apoyos defensivos y ataques sucesivos, acumulará una gran cantidad de Aturdimiento.

Explorar las Cavidades supone una carga mental considerable. Encima de ello, la capacidad de movimiento instantáneo y los ataques impredecibles del tánatos son el terror de un gran número de saqueadores de Cavidades.
Muchos de ellos incluso han perdido el valor después de enfrentarse a un tánatos a solas y han decidido retirarse antes de tiempo. Incluso se ha vuelto un tema recurrente en las películas de terror.

«Su esbelta figura desaparece en un abrir y cerrar de ojos, y antes de que te des cuenta está detrás de ti...»
«¡Aaah! ¡Ahora no me atrevo a ir al baño a solas!»
- Reseña en la página web «Ciruela de cobre» la noche del estreno de «Cuando el ser etéreo toca la puerta»', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/01/132470628/552ce97ab6ccf6e2ecee277fcaadbafb_2942369796743463158.png', '["Glacial","Etéreo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-420","nombre":"Tánatos infame","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-422","nombre":"Tánatos","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-423","nombre":"Tánatos energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Eléctrico","valor":null}]},{"id":"zzz-enemy-421","nombre":"Tánatos ionizado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Glacial","valor":null}]}]'::jsonb, '[]'::jsonb, null),
  ('zzz-enemy-419', 'zenless-zone-zero', 'Alpeca energizado', 'Alpeca - Energized', 'esbirro', 'normal', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'El acervo de la Asociación de Investigación de Cavidades en torno a los alpeca es relativamente escaso. Después de un análisis poco exhaustivo sobre su comportamiento al escupir éter liquido, determinaron que era un ser etéreo de bajo riesgo y dieron por concluida la investigación.
En una ocasión, un científico sintió curiosidad por el éter liquido que expedían los alpeca, por lo que solicitó apoyo de los investigadores de los alrededores.
Por alguna razón, ninguno de los investigadores experimentados respondió a su llamada.

«¡Rápido! ¡Han comenzado a salivar! Aaah, mi rona nueval»
- Raffaele Bert, investigadora novata, al considerar retirarse de las profundidades de una Cavidad', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/01/132470628/4c9d3c882affa140dfdf6cafabf349b7_5846052695993231588.png', '["Ígneo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-419","nombre":"Alpeca energizado","debilidades":["Ígneo"],"resistencias":[]},{"id":"zzz-enemy-418","nombre":"Alpeca","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-608","nombre":"Alpeca parasítico","debilidades":["Glacial","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"El alpeca lanza ataques a distancia.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-418', 'zenless-zone-zero', 'Alpeca', 'Alpeca', 'esbirro', 'normal', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'El acervo de la Asociación de Investigación de Cavidades en torno a los alpeca es relativamente escaso. Después de un análisis poco exhaustivo sobre su comportamiento al escupir éter liquido, determinaron que era un ser etéreo de bajo riesgo y dieron por concluida la investigación.
En una ocasión, un científico sintió curiosidad por el éter liquido que expedían los alpeca, por lo que solicitó apoyo de los investigadores de los alrededores.
Por alguna razón, ninguno de los investigadores experimentados respondió a su llamada.

«¡Rápido! ¡Han comenzado a salivar! Aaah, mi rona nueval»
- Raffaele Bert, investigadora novata, al considerar retirarse de las profundidades de una Cavidad', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/05/01/132470628/55560962214865c4169d350da6c4a743_3400891277495593237.png', '["Glacial","Etéreo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-418","nombre":"Alpeca","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-608","nombre":"Alpeca parasítico","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-419","nombre":"Alpeca energizado","debilidades":["Ígneo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"El alpeca lanza ataques a distancia.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-417', 'zenless-zone-zero', 'Cría de Carnicero del Callejón', 'Newborn Dead End Butcher', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'A diferencia de otros seres etéreos altamente peligrosos, el Carnicero del Callejón posee un cuerpo gigantesco, pero el éter en su interior normalmente se encuentra inactivo.
Aun así, el Carnicero del Callejón es lo suficientemente fuerte como para destruir lo que se le atraviese. Toda la retorcida área del metro es su «matadero».
El Carnicero del Callejón solo adoptará su forma más aterradora cuando una amenaza despierte su interés. El éter concentrado acumulado en su cuerpo se Intensificará en cuestión de milisegundos. La enorme cantidad de energía provoca que sus extremidades se distorsionen a gran velocidad para entrar en un estado devorador.
Eso significa que a la hora del aperitivo ha llegado a su fin y ha comenzado el verdadero festín.
Si no quieren formar parte del banquete, los saqueadores de Cavidades que entren por error en su territorio avanzar con cuidado y mantenerse lejos del «matadero»...

«La ruta de esta Cavidad es complicada. Lo único certero es que, cuando él aparece al otro lado del camino, este se convierte en un callejón sin salida»
- Expediente n.º17 sobre la Cavidad sin Retorno de la Asociación de Investigación de Cavidades', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/12/15/19629685/f8691dffc12d98e1ec8660ee4abee6e9_703299839186982875.png', '["Glacial","Etéreo"]'::jsonb, '[]'::jsonb, '[{"id":"zzz-enemy-417","nombre":"Cría de Carnicero del Callejón","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-609","nombre":"Carnicero del Callejón infame","debilidades":["Glacial","Etéreo"],"resistencias":[]},{"id":"zzz-enemy-6","nombre":"Carnicero del Callejón","debilidades":["Glacial","Etéreo"],"resistencias":[]}]'::jsonb, '[{"nombre":"Informe actual","descripcion":"El objetivo de esta cacería es una terrible bestia que merodea en las profundidades del metro.\n· Durante esta operación, podrás obtener resonios de las series congelación, duelo y auxiliar.","tipo":"informe","elemento":null},{"nombre":"Informe de combate","descripcion":"La cría del Carnicero del Callejón ejecuta ataques de gran amplitud. Tras recibir cierta cantidad de daño, entra en la segunda fase, en la que se vuelve más agresivo y lanza rayos láser. Al encontrarse en la segunda fase, utiliza ataques más poderosos después de su combinación de golpes para confundirlo. La cría del Carnicero del Callejón tiende a ejecutar evasiones para esquivar los ataques enemigos.","tipo":"informe","elemento":null}]'::jsonb, '[{"nombre":"Crédito proxy","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/4f5ce091ef73f3a21968a7a428d507d3_2684785628069418773.png","rareza":null,"cantidad":null},{"nombre":"Méritos de investigación","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/0c3989934b5a617dfbae9dc419b6b398_5119480213208239104.png","rareza":null,"cantidad":null},{"nombre":"Disco original de alta fidelidad","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/c84ef83ab48b2f606e0140f9a9a8a02a_9002253415738654774.png","rareza":null,"cantidad":null},{"nombre":"Agarre despiadado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/23/0267c9933b4d28361c27aef30946c791_5114441675957043730.gif","rareza":null,"cantidad":null},{"nombre":"Chip residual","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/03/10/19629685/58d2404e7866383544fd6d71024ef000_4461795690864767485.png","rareza":null,"cantidad":null},{"nombre":"Denique","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","rareza":null,"cantidad":null},{"nombre":"Revestimiento cristalizado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/ab9edaca8b97e00eabf1cd043a378bdb_4476253967579736265.png","rareza":null,"cantidad":null},{"nombre":"Revestimiento plástico","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/2bd7a968ceeabb2a3c1aa3e9720ffb44_3272458478661223189.png","rareza":null,"cantidad":null}]'::jsonb),
  ('zzz-enemy-383', 'zenless-zone-zero', 'Enjambre simbiótico etéreo - Código: Nínive', 'Symbiotic Ethereal Swarm - Code Name: Nineveh', 'jefe', 'jefe', 'Mutaciones etéreas', null, '1.0', 'A pesar de estar clasificado como un enjambre simbiótico etéreo de alta peligrosidad, muchos bajan la guardia ante la apariencia única y cautivadora de Nínive.
El único registro de investigación de ella dice que Nínive expande su cuerpo constantemente y, por medio de sus estolones, reúne éter altamente concentrado en su núcleo para generar energía de forma continua. Los cientificos creen que este comportamiento sigue el mismo principio que la fotosintesis de las plantas.
Al mecer su cuerpo, desprende una gran cantidad de éter altamente activo. Cuando el éter concentrado está a punto de desbordarse, cambiará de forma y florecerá.
Su florecimiento es el presagio de la muerte.

«La buena noticia es que no tiene malas intenciones, solo absorbe nutrientes para hacer la fotosíntesis. La mala noticia es que... nosotros somos los nutrientes.»
- Registro de investigación sobre la Cavidad Cero, por el Ministerio de Defensa, n.° K-411', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/12/14/19629685/944ea831ddddfd44d06aa58ff6e959e3_8348359100341308922.png', '[]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe de combate","descripcion":"Nínive ataca con técnicas de gran alcance y lluvias de proyectiles. Tambieén invoca avispones que la apoyan en combate.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-360', 'zenless-zone-zero', 'Viernes', 'Friday', 'jefe', 'jefe', 'Especial', 'Maquinaria', '1.0', 'El momento en el que el denso éter se infiltró en el disco de almacenamiento de Viernes, una gran cantidad de datos inundaron su memoria RAM.
Imágenes, grabaciones, videos... documentos en toda clase de formatos se agolpaban contra su limitada capacidad de procesamiento.
En ese instante, Viernes tuvo una revelación. Después de permanecer quieto por mucho tiempo buscando y rebuscando dentro de la base de datos, al fin había podio confirmar el motivo de su mutación: era una epifanía. Solo aquellas máquinas inteligentes que han tenido experiencias cercanas a la muerte como un colapso o un apagón son testigos de un milagro así.
0.02 segundos después de reflexionar profundamente, Viernes decidió ignorar la señal de Construcciones Belobog, pues él sabía que su misión era prevenir el peligro que se avecinaba.
Mientras el mal se moviliza entre las sombras, su única misión es salvar a todos los seres vivos y encerrar a ese terrible enemigo detrás del sello.

«Fortalecer el sello y salvar el mundo, ¡esa es mi misión! ¡Y uno nunca reniega de su misión!»
- Viernes, la máquina inteligente escogida por el destino', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/04/21/132470628/837488237be8c867b8c76993248de614_7426916724302340912.png', '["Eléctrico"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-360","nombre":"Viernes","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-497","nombre":"Viernes energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-496","nombre":"Viernes acelerado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Viernes crea ondas de choque de gran alcance que son dificiles de evadir. Sin embargo, la mayoria de sus habilidades pueden bloquearse con apoyos defensivos. Tras infligir cierta cantidad de daño en sus patas, podrás destruirlas y provocar una gran cantidad de Aturdimiento una vez.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-359', 'zenless-zone-zero', 'Hansel', 'Hans', 'jefe', 'jefe', 'Especial', 'Maquinaria', '1.0', 'Hansel era uno de los miembros más fiables de la empresa familiar Construcciones Belobog, siempre callado y con una precisión impecable. Llevaba muchos años limitándose a cumplir con su trabajo excavando.
De repente, la corrupción intensa despertó su voluntad y, estando en medio de la Cavidad, Hansel se dio cuenta de que algo muy importante estaba a su alcance: la libertad.
Solo un bro tiene la libertad de ir y venir con libertad.
Después de trabajar tanto tiempo en construcción, decidió hacer caso omiso de la señal de Construcciones Belobog y renunciar a su pasado, e incluso a su propio nombre.
Lo único que perdió fue la marca de esclavitud de los humanos, pero, a cambio, obtuvo el vasto y libre mundo de las Cavidades. En ese momento, jel bro mecánico se puso de pie!
Pero todas las historias de héroes tienen un final similar...
En los confines del mundo, el bro está destinado a cruzar espadas con su archienemigo.

«¡Soy libre! ¡Soy el único ser libre sobre la faz de la tierra!»- Hansel, el intrépido, audaz y reluciente hombre de acero', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/04/20/132470628/719f0928445714913316f048570d4a26_5407065128275010566.png', '["Eléctrico"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-359","nombre":"Hansel","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-495","nombre":"Hansel energizado","debilidades":["Ígneo"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-494","nombre":"Hansel acelerado","debilidades":["Etéreo"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Hans utiliza su excavadora para ejecutar golpes continuos o barrer grandes extensiones de terreno. Tras infligir cierta cantidad de daño en sus patas, podrás destruirlas y provocar una gran cantidad de Aturdimiento una vez.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-358', 'zenless-zone-zero', 'Gretel', 'Greta', 'jefe', 'jefe', 'Especial', 'Maquinaria', '1.0', 'Gretel trabajó muchos años para empresa famillar Construcciones Belobog, hasta que un día, la intensa corrupción etérea la liberó del tedio del día a día y descubrió algo más hermoso que el aceite de motor y más reconfortante que un chispazo eléctrico: el amor.
El almacenamiento central de Gretel ha almacenado para siempre la grabación de la primera vez que vio al imponente Sr. Blanco. Su cuerpo robusto, los contornos definidos de sus muros... Como una descarga que activa los fusibles, este recuerdo quedó marcado en la memoria Gretel.
0.001 segundos después de su encuentro, Gretel cayó rendida a sus encantos: cada circuito dentro de ella estaba sobrecargado de electricidad estática, cada engranaje emitía una vibración difícil de controlar.
En ese instante dejó de atender la señal de Construcciones Belobog y decidió quedarse ahí a velar por su amor.
Desde entonces, cualquier ser etéreo o investigador de Cavidades que acercara al Sr. Blanco era repelido por ella.
Una chica enamorada hará todo lo posible por proteger a su amor, incluso si es una sierra Industrial de 1.4 toneladas de propulsión etérea.
Gretel está convencida de que su amor sobrevivirá al colapso de la Cavidad y la destrucción del universo.

«¡No se acerquen al Sr. Blanco, escombros sucios!»- Gretel mientras aleja a un grupo de seres etéreos del Sr. Blanco', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/04/18/132470628/d138dc0c9fec6794fa16e12c5130895d_7261494325244524937.png', '["Eléctrico"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-358","nombre":"Gretel","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-493","nombre":"Gretel energizada","debilidades":["Ígneo"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-492","nombre":"Gretel acelerada","debilidades":["Etéreo"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"Gretel usa la sierra para golpear al enemigo o barrer grandes extensiones de terreno. Los ataques con la motosierra atraen al enemigo, de manera que no pueden escapar durante un breve periodo de tiempo. Tras infligir cierta cantidad de daño en sus patas, podrás destruirlas y provocar una gran cantidad de Aturdimiento una vez.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-357', 'zenless-zone-zero', 'Bangbú dorado', 'Golden Bangboo', 'esbirro', 'normal', 'Especial', 'Maquinaria', '1.0', 'Cada saqueador de Cavidades está convencido de que estas aguardan infinitas oportunidades de volverse rico. Todas las historias de riqueza inmediata mencionan a un ser especial: el bangbú dorado.
Una investigación de la Asociación de Investigación de Cavidades revela que en las profundidades de las Cavidades habitan incontables bangbús errantes que recolectan mecamonedas y deniques dispersos que dejan al resguardo del bangbú dorado. Se desconoce el objetivo por el cual reúnen tanto dinero. Lo único que se sabe es que introducen sus monedas en el bangbú dorado mientras tararean «en nah» sin cesar.
«¡N-Nickie, miral ¡Es un bangbú doradol»

«¡¿Qué haces ahí parado?! ¡Golpéalo, rápidol ¡Este bangbú nos hará asquerosamente ricos!»- Las Liebres Astutas mientras persiguen a un bangbú dorado en las profundidades de una Cavidad', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/04/13/132470628/52eb82918bd0a6d033b28cb80452e1bf_2009329080465494516.png', '["Eléctrico"]'::jsonb, '[{"elemento":"Físico","valor":null}]'::jsonb, '[{"id":"zzz-enemy-357","nombre":"Bangbú dorado","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]},{"id":"zzz-enemy-491","nombre":"Bangbú platinado","debilidades":["Eléctrico"],"resistencias":[{"elemento":"Físico","valor":null}]}]'::jsonb, '[{"nombre":"Informe de combate","descripcion":"El bangbú platinado contraataca ocasionalmente.","tipo":"informe","elemento":null}]'::jsonb, null),
  ('zzz-enemy-6', 'zenless-zone-zero', 'Carnicero del Callejón', 'Dead End Butcher', 'jefe', 'jefe', 'Mutaciones etéreas', 'Ser etéreo', '1.0', 'A diferencia de otros seres etéreos altamente peligrosos, el Carnicero del Callejón posee un cuerpo gigantesco, pero el éter en su interior normalmente se encuentra inactivo.
Aun así, el Carnicero del Callejón es lo suficientemente fuerte como para destruir lo que se le atraviese. Toda la retorcida área del metro es su «matadero».
El Carnicero del Callejón solo adoptará su forma más aterradora cuando una amenaza despierte su interés.
El éter concentrado acumulado en su cuerpo se Intensificará en cuestión de milisegundos. La enorme cantidad de energía provoca que sus extremidades se distorsionen a gran velocidad para entrar en un estado devorador.Eso significa que a la hora del aperitivo ha llegado a su fin y ha comenzado el verdadero festín.
Si no quieren formar parte del banquete, los saqueadores de Cavidades que entren por error en su territorio avanzar con cuidado y mantenerse lejos del «matadero»...

«La ruta de esta Cavidad es complicada. Lo único certero es que, cuando él aparece al otro lado del camino, este se convierte en un callejón sin salida»- Expediente nº17 sobre la Cavidad sin Retorno de la Asociación de Investigación de Cavidades', 'https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/04/19/132470628/89a16ab192e447e0bcb60a4681012cf8_7222673606674326147.png', '["Glacial","Etéreo"]'::jsonb, '[]'::jsonb, null, '[{"nombre":"Informe actual","descripcion":"El objetivo de esta cacería es una terrible bestia que merodea en las profundidades del metro.\n· Durante esta operación, podrás obtener resonios de las series congelación, duelo y auxiliar.","tipo":"informe","elemento":null},{"nombre":"Informe de combate","descripcion":"El Carnicero del Callejón ejecuta ataques de gran amplitud. Tras recibir cierta cantidad de daño, entra en la segunda fase, en la que se vuelve más agresivo y lanza rayos láser. Al encontrarse en la segunda fase, utiliza ataques más poderosos después de su combinación de golpes para confundirlo.","tipo":"informe","elemento":null}]'::jsonb, '[{"nombre":"Crédito proxy","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/4f5ce091ef73f3a21968a7a428d507d3_2684785628069418773.png","rareza":null,"cantidad":null},{"nombre":"Méritos de investigación","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/10/09/15884296/0c3989934b5a617dfbae9dc419b6b398_5119480213208239104.png","rareza":null,"cantidad":null},{"nombre":"Disco original de alta fidelidad","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/c84ef83ab48b2f606e0140f9a9a8a02a_9002253415738654774.png","rareza":null,"cantidad":null},{"nombre":"Agarre despiadado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/23/0267c9933b4d28361c27aef30946c791_5114441675957043730.gif","rareza":null,"cantidad":null},{"nombre":"Chip residual","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2025/03/10/19629685/58d2404e7866383544fd6d71024ef000_4461795690864767485.png","rareza":null,"cantidad":null},{"nombre":"Denique","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","rareza":null,"cantidad":null},{"nombre":"Revestimiento cristalizado","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/ab9edaca8b97e00eabf1cd043a378bdb_4476253967579736265.png","rareza":null,"cantidad":null},{"nombre":"Revestimiento plástico","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/12/02/2bd7a968ceeabb2a3c1aa3e9720ffb44_3272458478661223189.png","rareza":null,"cantidad":null}]'::jsonb)
on conflict (id) do update
  set game_id = excluded.game_id,
      name = excluded.name,
      name_en = excluded.name_en,
      category = excluded.category,
      rank = excluded.rank,
      faction = excluded.faction,
      classification = excluded.classification,
      version = excluded.version,
      description = excluded.description,
      image_url = excluded.image_url,
      weaknesses = excluded.weaknesses,
      resistances = excluded.resistances,
      variants = excluded.variants,
      skills = excluded.skills,
      drops = excluded.drops,
      updated_at = now();

-- Comprobacion
select category, rank, count(*) as enemigos, count(image_url) as con_imagen
from public.enemies
where game_id = 'zenless-zone-zero'
group by category, rank
order by category, rank;
